  write(fileB, "# Beta\n\nBETA_V14\n");
  await sleep(2400);
  check(
    "a dismissed prompt does not suppress the next tab's prompt",
    promptedForA === true && (await promptShown()) === true,
    `promptedForA=${promptedForA} promptedForB=${await promptShown()}`,
  );

