  await sleep(1600);
  heldEditedReload.restore();
  const afterRace = await exec(`
    (() => {
      const a = window.CustomTabs.getTabs().find(t => t.id === ${ids.a});
      return { content: a.content, dirty: a.hasUnsavedChanges };
    })()
  `);
